### 参考答案  
**1. 方法区OOM的核心原因**  
方法区（Java 8后为元空间）存储类元数据、常量池、静态变量等。OOM主因是**类元数据堆积**：  
- **为什么**：动态生成大量类（如CGLIB代理、反射生成类）或缓存类对象未释放，导致元空间耗尽。  
- **怎么做**：  
  ```java
  // 示例：动态生成类导致元空间膨胀  
  Enhancer enhancer = new Enhancer();  
  enhancer.setSuperclass(MyClass.class);  
  enhancer.setCallback(...);  
  // 每次调用生成新类，未复用则持续占用元空间  
  ```  

**2. 线上案例与排查流程**  
**场景**：微服务中因动态代理类未缓存，导致元空间OOM。  
**排查步骤**：  
1. **监控告警**：通过Prometheus+Grafana发现`Metaspace`使用率突增。  
2. **GC日志分析**：`-XX:+PrintGCDetails`显示`Metaspace GC`频繁但回收量低。  
3. **Dump分析**：  
   ```bash  
   jmap -dump:format=b,file=heap.hprof <pid>  
   ```  
   用MAT查看`java.lang.Class`实例数异常，定位到动态代理类重复生成。  
4. **Arthas诊断**：  
   ```bash  
   classloader -l  // 查看类加载器  
   vmtool --action getInstances --className java.lang.Class --count 100  
   ```  

**3. 解决方案与优化**  
- **为什么有效**：减少类生成、复用类对象、限制元空间大小。  
- **怎么做**：  
  1. **代码层**：缓存动态代理类（如Spring AOP默认缓存）。  
  2. **配置层**：设置`-XX:MaxMetaspaceSize=256m`，避免无限占用本地内存。  
  3. **架构层**：  
     ```  
     应用启动 -> 类加载器 -> 元空间  
     |-> 优化：使用固定类加载器复用类  
     |-> 监控：通过Micrometer暴露Metaspace指标  
     ```  

**总结**：方法区OOM本质是类元数据管理失控，需结合监控、Dump分析和代码优化闭环解决。线上案例中，通过Arthas快速定位动态代理类泄漏，最终通过缓存机制将元空间使用率从90%降至30%。  

（字数：598）'),
