### LRU缓存实现参考答案  

**1. 核心思想与数据结构选择**  
- **为什么用哈希表+双向链表？**  
  LRU需快速定位数据（O(1)）并维护访问顺序（淘汰最久未用）。哈希表存键值映射，双向链表按访问时间排序，头部为最新，尾部为最旧。  
- **怎么做？**  
  ```java
  class LRUCache {
      Map<Integer, Node> map; // 哈希表：key -> 节点
      DoublyLinkedList list; // 双向链表：维护访问顺序
  }
  ```

**2. 关键操作实现**  
- **get()操作**  
  - **为什么移动节点？** 访问后需更新为“最新使用”，否则可能被误淘汰。  
  - **怎么做？**  
    ```java
    int get(int key) {
        if (map.containsKey(key)) {
            Node node = map.get(key);
            list.moveToHead(node); // 移到链表头部
            return node.value;
        }
        return -1;
    }
    ```  
- **put()操作**  
  - **为什么分情况处理？** 需区分“更新已有键”和“插入新键”，后者可能触发淘汰。  
  - **怎么做？**  
    ```java
    void put(int key, int value) {
        if (map.containsKey(key)) {
            Node node = map.get(key);
            node.value = value;
            list.moveToHead(node);
        } else {
            Node newNode = new Node(key, value);
            map.put(key, newNode);
            list.addHead(newNode);
            if (map.size() > capacity) {
                Node tail = list.removeTail(); // 淘汰最旧
                map.remove(tail.key);
            }
        }
    }
    ```

**3. 双向链表设计**  
- **为什么用哨兵节点？** 避免空指针判断，简化头尾操作。  
- **怎么做？**  
  ```java
  class DoublyLinkedList {
      Node head, tail; // 哨兵节点
      DoublyLinkedList() {
          head = new Node(0, 0);
          tail = new Node(0, 0);
          head.next = tail;
          tail.prev = head;
      }
  }
  ```

**4. 复杂度与边界处理**  
- **时间复杂度**：get/put均为O(1)，哈希表+链表操作无遍历。  
- **边界场景**：容量为0时直接返回；键不存在时get返回-1；put时容量满需先淘汰。  

**总结**：通过哈希表快速定位、双向链表维护顺序，实现高效LRU。实际场景中需注意线程安全（如加锁）和内存管理（如弱引用）。'),
