### 参考答案

**1. Spring Boot 的核心优势**  
- **为什么选它**：解决传统 Spring 项目配置繁琐的问题，通过约定优于配置（Convention over Configuration）快速启动项目。  
- **怎么做**：  
  - **自动配置**：通过 `@SpringBootApplication` 注解 + 条件化配置（如 `@ConditionalOnClass`）减少 XML 配置。例如，引入 `spring-boot-starter-web` 后自动配置 Tomcat 和 Spring MVC。  
  - **内嵌服务器**：直接运行 `java -jar` 启动应用，无需手动部署 WAR 包。  
  - **起步依赖**：通过 `spring-boot-starter-*` 统一依赖管理，避免版本冲突。  

**2. Spring Cloud 的微服务治理能力**  
- **为什么选它**：提供完整的微服务生态，解决分布式系统常见痛点。  
- **怎么做**：  
  - **服务注册与发现**：集成 Eureka/Nacos 实现服务自动注册（如 `@EnableEurekaClient`）。  
  - **负载均衡与熔断**：通过 Ribbon 实现客户端负载均衡，Hystrix 提供熔断降级（如 `@HystrixCommand`）。  
  - **配置中心**：Spring Cloud Config 集中管理多环境配置，支持动态刷新。  

**3. 对比其他框架的优势**  
- **vs Dubbo**：  
  - **生态完整性**：Spring Cloud 提供网关（Zuul/Gateway）、链路追踪（Sleuth）等一站式方案，Dubbo 需额外集成。  
  - **HTTP 友好**：基于 RESTful 设计，更适合前后端分离场景。  
- **vs Quarkus/Micronaut**：  
  - **学习成本**：Spring 社区成熟，文档丰富，团队上手快。  
  - **扩展性**：通过 Starter 机制灵活扩展，而 Quarkus 更侧重云原生场景。  

