### Java对象创建流程解析  

#### 1. **类加载阶段**  
**为什么需要类加载？**  
JVM需确保类结构合法且安全，避免运行时错误。例如，恶意代码可能破坏JVM稳定性。  
**怎么做？**  
- **加载**：通过类加载器（如Bootstrap/Extension/AppClassLoader）读取`.class`文件到内存。  
- **验证**：检查字节码格式、符号引用等（如`javap -v MyClass`可验证结构）。  
- **准备**：为静态变量分配内存并赋默认值（如`static int a = 0`）。  
- **初始化**：执行`<clinit>`方法（静态代码块和静态变量赋值）。  

```ascii
类加载流程：
Loading -> Verification -> Preparation -> Resolution -> Initialization
```

---

#### 2. **内存分配阶段**  
**为什么需要分配内存？**  
对象需在堆中存储，需高效管理内存空间。  
**怎么做？**  
- **分配策略**：  
  - **指针碰撞**：堆内存规整时（如Eden区），直接移动指针（`malloc`类似逻辑）。  
  - **空闲列表**：堆碎片化时，维护空闲链表查找可用块。  
- **优化**：使用TLAB（Thread Local Allocation Buffer）减少线程竞争，提升分配效率。  

```ascii
内存分配区域：
Heap -> Eden Space -> TLAB (Thread Local)
```

---

#### 3. **初始化阶段**  
**为什么需要初始化？**  
确保对象状态正确，依赖关系（如父类字段）被正确设置。  
**怎么做？**  
- **实例初始化顺序**：  
  1. 父类静态块 → 子类静态块（类加载时已执行）。  
  2. 父类实例初始化 → 子类实例初始化（如`{ int x = 1; }`）。  
  3. 构造函数执行。  

```java
// 示例：初始化顺序验证
class Parent { 
    { System.out.println("Parent Instance"); } 
    Parent() { System.out.println("Parent Constructor"); } 
}
class Child extends Parent { 
    { System.out.println("Child Instance"); } 
    Child() { System.out.println("Child Constructor"); } 
}
// 输出顺序：Parent Instance -> Parent Constructor -> Child Instance -> Child Constructor
```

---

### 总结  
对象创建是JVM核心机制，涉及**类加载的严格验证**、**内存分配的高效策略**及**初始化的有序执行**。理解这些步骤可帮助优化性能（如调整TLAB大小）和排查问题（如`OutOfMemoryError`）。'),
  ('java-012', '

### 参考答案

**核心区别**  
`==` 比较的是对象的**内存地址**（引用是否指向同一对象），而 `equals()` 默认行为与 `==` 相同，但可通过重写实现**内容比较**。  
**为什么**：Java 设计 `==` 用于快速判断引用关系，而 `equals()` 作为可定制接口，满足业务层面对"逻辑相等"的需求。  
**怎么做**：  
- 若需比较对象内容（如字符串值、用户ID等），必须重写 `equals()`。  
- 例如：`String s1 = new String("abc"); String s2 = new String("abc");`  
  `s1 == s2` 返回 `false`（不同对象），但 `s1.equals(s2)` 返回 `true`（内容相同）。

---

**String 重写 equals 的底层逻辑**  
String 的 `equals()` 方法通过**逐字符比较**实现内容相等性：  
```java
public boolean equals(Object anObject) {
    if (this == anObject) return true; // 地址相同直接返回
    if (anObject instanceof String) {
        String anotherString = (String)anObject;
        int n = value.length;
        if (n == anotherString.value.length) {
            char v1[] = value;
            char v2[] = anotherString.value;
            for (int i = 0; i < n; i++)
                if (v1[i] != v2[i]) return false;
            return true;
        }
    }
    return false;
}
```  
**为什么**：避免开发者手动实现复杂的内容比较逻辑，同时保证字符串比较的**安全性**（如空指针处理、类型校验）。  
**怎么做**：重写时需遵循契约（自反性、对称性等），并同步重写 `hashCode()` 以兼容哈希集合。

---

**为什么要重写 equals？**  
**为什么**：  
1. **业务语义需求**：例如用户对象 `User` 需通过 `id` 判断是否同一用户，而非内存地址。  
2. **集合操作依赖**：`HashSet`、`HashMap` 依赖 `equals()` 判断元素唯一性。  
**怎么做**：  
```java
class User {
    int id;
    String name;
    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof User)) return false;
        User user = (User) o;
        return id == user.id; // 仅比较id
    }
}
```  
**实际场景**：在电商系统中，订单对象通过 `orderNo` 重写 `equals()`，确保重复提交订单时能正确识别。

---

**总结**  
`==` 是底层引用比较，`equals()` 是面向业务的内容比较工具。String 的重写体现了 Java 对高频场景的优化，而自定义类重写 `equals()` 是实现"逻辑相等"的关键手段。'),
  ('java-011', '

### Java对象申请流程详解  

**1. 类加载与验证**  
**为什么**：JVM需确保类的合法性与安全性，避免运行时错误。  
**怎么做**：  
- 遇到`new`指令时，JVM检查类是否已加载。若未加载，通过`ClassLoader`加载字节码，执行**加载→验证→准备→解析→初始化**五步。  
- 验证阶段检查字节码格式、语义正确性（如访问权限）；准备阶段为类变量分配内存并赋默认值（如`int=0`）。  
**示例**：  
```java
public class User { private String name; } // 类加载后，name初始化为null
```

**2. 内存分配**  
**为什么**：对象需存储在堆内存中，保证生命周期独立于线程。  
**怎么做**：  
- JVM根据堆布局选择分配策略：  
  - **指针碰撞**（堆规整时）：直接移动空闲内存指针。  
  - **空闲列表**（堆碎片化时）：从空闲列表中选取合适块。  
- 多线程下通过**TLAB（线程本地分配缓冲区）**减少竞争，提升效率。  
**场景**：高频创建对象时，TLAB可避免锁竞争，如Web服务中短生命周期对象。

**3. 对象初始化**  
**为什么**：确保对象状态符合业务逻辑，避免未初始化成员引发异常。  
**怎么做**：  
- **对象头设置**：写入哈希码、GC分代年龄、锁状态等元数据。  
- **实例变量初始化**：按声明顺序赋默认值（如`int=0`），再执行实例初始化块和构造方法。  
**示例**：  
```java
public class User {
    private String name = "Default"; // 显式初始化
    { System.out.println("初始化块"); } // 实例初始化块
    public User(String name) { this.name = name; } // 构造方法
}
// 执行顺序：默认值→初始化块→构造方法
```

**4. 优化机制（补充）**  
- **逃逸分析**：若对象未逃逸出方法，可能栈上分配（如局部变量），减少堆压力。  
- **标量替换**：将对象拆分为独立字段，进一步优化内存使用。  

**总结**：对象创建是类加载、内存分配、初始化的协同过程，JVM通过TLAB、逃逸分析等机制平衡性能与安全。理解流程有助于优化高并发场景下的内存管理。'),
  ('java-010', '

### 参考答案（口头表达版）

在Java中，**直接在for循环中删除列表元素会导致两种典型问题**：  
1. **增强for循环（for-each）触发`ConcurrentModificationException`**  
2. **传统for循环因索引错位导致逻辑错误**  

---

#### **问题根源分析**  
**为什么会出现异常？**  
- **增强for循环**本质是迭代器遍历，若遍历时直接调用`list.remove()`，会破坏迭代器的`expectedModCount`计数器，触发快速失败机制。  
  ```java
  // 错误示例：直接删除
  for (String item : list) { 
      if (item.equals("target")) list.remove(item); // 抛出异常
  }
  ```
- **传统for循环**删除元素后，后续元素索引前移，导致**跳过元素**或**越界**。  
  ```java
  // 错误示例：索引错位
  for (int i = 0; i < list.size(); i++) {
      if (list.get(i).equals("target")) list.remove(i); 
      // 删除后i++，导致下一个元素被跳过
  }
  ```

---

#### **解决方案与原理**  
**1. 使用迭代器的`remove()`方法（推荐）**  
- **为什么有效？**  
  迭代器提供安全的`remove()`方法，内部会同步更新`modCount`，避免结构修改冲突。  
- **怎么做？**  
  ```java
  Iterator<String> iter = list.iterator();
  while (iter.hasNext()) {
      if (iter.next().equals("target")) iter.remove();
  }
  ```

**2. 倒序遍历删除（适用于传统for循环）**  
- **为什么有效？**  
  从后往前删除时，已遍历的索引不受影响，避免索引错位。  
- **怎么做？**  
  ```java
  for (int i = list.size() - 1; i >= 0; i--) {
      if (list.get(i).equals("target")) list.remove(i);
  }
  ```

**3. 收集待删除元素后批量处理**  
- **为什么有效？**  
  分离遍历与修改操作，彻底规避并发修改问题。  
- **怎么做？**  
  ```java
  List<String> toRemove = new ArrayList<>();
  for (String item : list) {
      if (item.equals("target")) toRemove.add(item);
  }
  list.removeAll(toRemove);
  ```

**4. Java 8 Stream过滤（代码简洁）**  
- **为什么有效？**  
  通过流式操作生成新集合，避免原地修改。  
- **怎么做？**  
  ```java
  List<String> filtered = list.stream()
      .filter(item -> !item.equals("target"))
      .collect(Collectors.toList());
  ```

---

#### **总结建议**  
- **优先选迭代器`remove()`**：性能高且语义清晰，适合单线程场景。  
- **倒序遍历**：简单场景快速解决，但需注意空指针风险。  
- **批量删除/Stream**：适合复杂条件或需保留原集合不可变性的场景。  

**关键点**：理解迭代器的快速失败机制和索引动态变化是解决问题的核心，实际开发中应根据性能、可读性权衡方案。'),
  ('java-015', '

### HashMap 并发安全问题及 1.8 循环链表分析  

#### 1. **并发安全问题的本质**  
**为什么？**  
- **多线程扩容冲突**：当多个线程同时触发 `resize()` 时，可能因哈希冲突导致数据覆盖或链表成环（1.7 典型问题）。  
- **非原子操作**：`put()` 中的 `table[i] = newNode` 等步骤非原子，多线程下可能丢失数据。  

**怎么做？**  
- **替代方案**：使用 `ConcurrentHashMap`（JDK 1.8+），其通过 **CAS + 分段锁** 实现线程安全：  
  ```java
  ConcurrentHashMap<String, Integer> map = new ConcurrentHashMap<>();
  map.put("key", 1); // 自动处理并发
  ```  
- **避免混用**：禁止在多线程中直接使用 `HashMap`，即使单线程场景也需明确线程模型。  

---

#### 2. **JDK 1.8 是否还会出现循环链表？**  
**为什么？**  
- **1.7 头插法缺陷**：扩容时采用头插法，多线程下链表可能形成环（如 A→B→C 扩容后变为 A→C→B→A）。  
- **1.8 尾插法优化**：改为尾插法，扩容时链表顺序保持不变，**彻底消除循环链表风险**。  

**怎么做？**  
- **源码验证**：1.8 的 `resize()` 中，新链表节点按原顺序追加到桶末尾：  
  ```java
  // 1.8 扩容逻辑片段
  if (loHead != null) {
      nextTab[j] = loHead; // 直接指向原链表头
  }
  ```  
- **仍需警惕并发**：虽无环，但多线程 `put()` 仍可能导致数据覆盖（如两个线程同时修改同一桶）。  

---

#### 3. **架构对比：1.7 vs 1.8 扩容机制**  
```
1.7 头插法扩容（危险）:
原链表: A -> B -> C 
扩容后: A -> C -> B -> A (成环)

1.8 尾插法扩容（安全）:
原链表: A <- B <- C 
扩容后: A <- B <- C (顺序不变)
```  

**结论**：  
- **1.8 不会循环链表**，但并发修改仍不安全。  
- **最佳实践**：高并发场景优先 `ConcurrentHashMap`，其通过 **Node 级锁** 和 **volatile 修饰** 保证线程安全。'),
  ('java-014', '

### 链表转红黑树阈值设计原理（JDK 8+ HashMap）

#### 1. **阈值选择的性能平衡逻辑**
   - **为什么是8？**  
     当链表长度超过8时，红黑树查找效率（O(log n)）显著优于链表（O(n)）。但树化操作本身需O(n log n)时间，因此需通过实验确定临界值。OpenJDK团队通过大量测试发现，8是哈希冲突概率与转换成本的平衡点：  
     - 若阈值过低（如5），频繁树化导致性能损耗；  
     - 若阈值过高（如10），链表过长时查找效率下降明显。  
     *示例场景*：1000次随机哈希冲突测试中，8作为阈值可使平均查找耗时降低40%。

   - **为什么退化阈值是6？**  
     退化阈值需低于树化阈值（8），避免频繁切换。当节点数≤6时，红黑树维护开销（额外指针、旋转操作）超过链表收益。设置6作为退化阈值，确保：  
     - 树化后节点减少时不会立即回退；  
     - 预留2个节点缓冲（8→6），减少抖动。  

#### 2. **源码实现中的关键约束**
   - **桶数量限制**：仅当`table.length ≥ 64`时才触发树化，否则优先扩容（避免小表树化浪费空间）。  
   - **哈希分布检测**：若链表节点哈希值分布均匀（`binCount`统计），说明哈希函数合理，无需树化。  

#### 3. **实际场景验证**
   ```java
   // HashMap树化逻辑片段
   if (binCount >= TREEIFY_THRESHOLD) {
       treeifyBin(table, hash); // 检查桶数量是否≥64
   }
   ```
   - **退化示例**：删除节点后，若树中节点数≤6，自动转为链表：  
     ```java
     if (root.left == null || root.right == null) {
         moveRootToFront(tab, p); // 转为链表头节点
     }
     ```

#### 4. **设计哲学总结**
   - **空间换时间**：红黑树用额外内存换取查询效率，阈值设计需综合考量场景；  
   - **动态适应**：通过双阈值（8/6）避免频繁转换，体现JDK对极端场景的防御性编程。  

> **面试加分点**：可补充“若哈希函数设计差（如全冲突），即使阈值8仍可能退化，此时需优化哈希算法而非调整阈值”。'),
  ('java-013', '

### HashMap 1.7/1.8 核心逻辑解析  

#### 1. **底层结构差异**  
- **1.7**：`数组 + 链表`，采用**头插法**。  
  - **为什么**：链表插入效率高，但并发扩容时易形成环形链表（死循环）。  
  - **怎么做**：通过 `index = (h & 0x7FFFFFFF) % length` 定位桶位置，冲突时新节点插入链表头部。  

- **1.8**：`数组 + 链表 + 红黑树`，采用**尾插法**。  
  - **为什么**：避免死循环，链表长度≥8时转为红黑树，提升查询效率（O(logn)）。  
  - **怎么做**：链表长度达阈值时触发树化，红黑树节点继承 `TreeNode` 类，支持树形遍历。  

```plaintext
1.7结构：array -> [bucket1: node1->node2->... | bucket2: ...]  
1.8结构：array -> [bucket1: node1->node2->...->TreeNode | bucket2: ...]
```

---

#### 2. **Put 流程**  
- **步骤**：  
  1. **计算哈希**：`h = key.hashCode()`，1.8 增加扰动函数 `h ^ (h >>> 16)` 减少碰撞。  
  2. **定位索引**：`i = (n - 1) & h`（n 为数组长度，需为2的幂）。  
  3. **冲突处理**：  
     - 1.7：头插法插入链表。  
     - 1.8：尾插法，若链表长度≥8 且数组长度≥64，触发树化。  
  4. **更新值**：key 存在则覆盖，否则新增节点。  

- **为什么尾插法**：避免并发扩容时链表逆序导致死循环（1.7 的致命缺陷）。  

---

#### 3. **扩容机制**  
- **触发条件**：`size > threshold`（threshold = capacity × loadFactor，默认 0.75）。  
- **1.7**：  
  - 新容量 = 旧容量 × 2，所有节点重新计算索引，头插法可能导致死循环。  
- **1.8**：  
  - 节点位置仅两种可能：原索引 `i` 或 `i + oldCap`（无需重新计算哈希）。  
  - **为什么**：利用2的幂特性，通过 `hash & oldCap` 判断节点是否移动。  

```plaintext
扩容流程：  
oldCap=16 -> newCap=32  
node1 (hash=5) -> 5 & 16 = 0 → 保留原位置  
node2 (hash=21) -> 21 & 16 = 16 → 移动至 5+16=21
```

---

#### 4. **树化逻辑**  
- **条件**：链表长度 ≥8 且数组长度 ≥64（否则优先扩容）。  
- **为什么**：平衡查询效率，避免链表过长导致 O(n) 退化。  
- **怎么做**：遍历链表，构建红黑树节点，维护树结构（如旋转、平衡）。  

**总结**：1.8 通过尾插法、树化优化和高效扩容，解决了 1.7 的并发安全问题，并提升了极端场景下的性能。'),
  ('java-016', '

### ConcurrentHashMap 1.8 锁机制演进分析  

#### 1. **锁粒度细化：从段级到节点级**  
**为什么放弃分段锁？**  
- 1.7 的分段锁（Segment）将哈希表划分为固定数量的段，每段独立加锁。但高并发下，同一 Segment 内的多个桶仍会竞争锁，导致锁粒度不够细。  
- 1.8 改为 **CAS + Synchronized**，锁粒度细化到 **单个桶（Node 链表/红黑树头节点）**，仅在哈希冲突时锁住特定桶，无冲突时通过 CAS 无锁操作，大幅提升并发度。  

**怎么做？**  
- **CAS 操作**：插入时若桶为空，直接用 `Unsafe.compareAndSwapObject` 原子性写入 Node，避免加锁。  
- **Synchronized 锁**：若桶已存在节点，则对头节点加 `synchronized` 锁，仅阻塞对该桶的操作，其他桶不受影响。  
```java
// 简化版 put 逻辑  
if (tabAt(tab, i) == null) { // 桶为空，CAS 插入  
    if (casTabAt(tab, i, null, new Node(...))) break;  
} else { // 桶非空，锁住头节点  
    synchronized (node) { ... }  
}  
```

#### 2. **JVM 优化加持：Synchronized 性能提升**  
**为什么选择 Synchronized？**  
- 1.7 的 ReentrantLock 需维护锁对象状态，而 1.8 的 Synchronized 受益于 JVM 优化（如 **偏向锁、轻量级锁**），在低竞争场景下开销更低。  
- 1.8 的锁仅作用于链表/树头节点，持有时间短，进一步减少锁膨胀概率。  

#### 3. **内存效率与结构简化**  
**为什么放弃 Segment 结构？**  
- 1.7 的 Segment 数组需额外存储锁对象，内存占用更高；1.8 直接以 Node 数组作为底层结构，减少间接层。  
- 动态扩容时，1.8 通过 `transfer` 方法迁移节点，无需维护 Segment 的扩容逻辑，代码更简洁。  

#### 4. **实际场景对比**  
- **高并发写入**：1.8 的细粒度锁使多线程可并行操作不同桶，吞吐量提升显著。  
- **读操作**：1.8 的 `volatile` 修饰 Node 字段，保证可见性，读操作几乎无锁。  

#### 架构对比（ASCII 示意）  
```  
1.7 分段锁结构：  
Segment[0] -> (Node链表) |-> ReentrantLock  
Segment[1] -> (Node链表) |-> ReentrantLock  

1.8 桶级锁结构：  
Node[0] -> (Node链表/树) |-> Synchronized(头节点)  
Node[1] -> (Node链表/树) |-> Synchronized(头节点)  
```  

**总结**：1.8 通过 **CAS 减少无冲突场景的锁开销** + **Synchronized 细粒度锁** + **JVM 优化**，在性能、内存和代码复杂度上全面优于分段锁，成为高并发场景的最优解。'),
  ('java-017', '

### 参考答案：LinkedHashMap实现LRU原理与手写思路

#### 一、LinkedHashMap的LRU原理（为什么能实现LRU？）
LinkedHashMap通过**双向链表+哈希表**的组合实现LRU，核心依赖两点：
1. **双向链表维护访问顺序**  
   - 当`accessOrder=true`时，每次`get/put`操作会将节点移到链表尾部（表示"最近使用"）。
   - 链表头部始终是最久未使用的节点，适合LRU淘汰策略。
2. **`removeEldestEntry()`方法控制淘汰**  
   - 重写该方法，当`size() > capacity`时返回`true`，触发删除链表头节点。

```java
// 示例：配置LRU缓存
Map<String, String> lruCache = new LinkedHashMap<>(16, 0.75f, true) {
    @Override
    protected boolean removeEldestEntry(Map.Entry eldest) {
        return size() > MAX_SIZE; // 超过容量时淘汰最旧节点
    }
};
```

---

#### 二、手写LRU的核心思路（怎么做？）
若从零实现LRU，需解决两个问题：
1. **快速访问与更新**  
   - 使用`HashMap`存储键值对（O(1)查找）。
   - 用**双向链表**维护访问顺序（头尾节点分别代表最久未用/最近使用）。
2. **节点移动与淘汰**  
   - 访问节点时，将其从链表原位置移除并移到尾部。
   - 新增节点时，若超过容量则删除链表头节点。

```java
// 简化版双向链表节点
class Node<K, V> {
    K key; V value; Node prev, next;
}
```

**关键操作逻辑**：
- `get(key)`：若命中，移动节点到尾部并返回值；否则返回null。
- `put(key, value)`：若键存在则更新值并移动节点；否则新增节点，超容则淘汰头节点。

---

#### 三、架构对比与选型建议
```
LinkedHashMap实现 vs 手写实现
|-> 优势：开箱即用，无需维护链表逻辑
|-> 劣势：无法自定义节点结构（如添加时间戳）

手写实现 vs 第三方库（如Guava Cache）
|-> 优势：完全控制逻辑，适合特殊场景
|-> 劣势：需处理并发安全（如加锁）
```

**面试加分点**：  
- 提到`LinkedHashMap`的`afterNodeAccess()`和`afterNodeInsertion()`钩子方法，说明其扩展性。
- 对比`ConcurrentHashMap`实现并发LRU的难点（如分段锁粒度）。

---

**总结**：LinkedHashMap通过`accessOrder`和`removeEldestEntry()`实现LRU，手写时需结合HashMap与双向链表。实际开发中优先选用LinkedHashMap，但需理解其底层逻辑以应对定制化需求。'),
  ('java-018', '

### synchronized锁升级流程解析  

**1. 偏向锁（Biased Locking）**  
- **为什么**：无竞争场景下，避免频繁CAS操作，提升性能。  
- **怎么做**：首次获取锁时，JVM通过CAS将对象头Mark Word中的线程ID记录为当前线程。后续同一线程进入同步块时，直接比对线程ID，无需再次加锁。  
  ```java  
  // 示例：单线程场景  
  synchronized(obj) {  
      // 首次进入：CAS设置偏向锁  
      // 后续进入：直接检查线程ID，跳过加锁逻辑  
  }  
  ```  

**2. 轻量级锁（Lightweight Locking）**  
- **为什么**：短暂竞争时，避免升级为重量级锁的上下文切换开销。  
- **怎么做**：当第二个线程竞争时，通过CAS尝试将对象头指向当前线程的Lock Record。若成功则自旋等待（默认10次），失败则升级为重量级锁。  
  ```java  
  // 示例：双线程竞争  
  synchronized(obj) {  
      // 线程1持有偏向锁，线程2尝试CAS失败  
      // 线程1撤销偏向锁，升级为轻量级锁  
      // 线程2自旋尝试获取锁  
  }  
  ```  

**3. 重量级锁（Heavyweight Locking）**  
- **为什么**：高竞争场景下，保证正确性，但依赖OS互斥量，性能开销大。  
- **怎么做**：自旋失败或更多线程竞争时，JVM将锁标记为重量级，线程进入阻塞队列，由OS调度唤醒。  
  ```java  
  // 示例：多线程高竞争  
  synchronized(obj) {  
      // 自旋次数超限 → 升级为重量级锁  
      // 线程阻塞，等待OS调度  
  }  
  ```  

**锁升级流程总结**  
```  
偏向锁 → (竞争) → 轻量级锁 → (自旋失败/高竞争) → 重量级锁  
```  
- **关键点**：  
  1. 偏向锁仅支持单线程，竞争时撤销（需全局安全点）；  
  2. 轻量级锁依赖自旋，避免阻塞；  
  3. 重量级锁通过OS保证互斥，但代价高。  

**实际场景**：  
- 单线程循环操作 → 偏向锁（无竞争）；  
- 双线程短竞争 → 轻量级锁（自旋快速解决）；  
- 多线程高频访问 → 重量级锁（如数据库连接池）。  

**延伸**：JDK 9后引入`-XX:+UseBiasedLocking`默认关闭，因现代硬件多核竞争更普遍，偏向锁收益降低。'),
  ('java-019', '

### 偏向锁撤销与重偏向触发条件  
**1. 偏向锁撤销时机**  
- **为什么撤销**：偏向锁仅适用于单线程场景，当检测到多线程竞争时需升级为轻量级/重量级锁。  
- **触发条件**：  
  - 其他线程尝试获取已偏向的锁（通过CAS竞争失败）  
  - 调用`wait()`/`notify()`（需进入阻塞队列）  
  - JVM参数`-XX:-UseBiasedLocking`禁用偏向锁  
  - **批量撤销**：当撤销次数超过阈值（默认20次），JVM会全局停止偏向锁分配（避免频繁升级开销）。  

**2. 重偏向触发条件**  
- **为什么重偏向**：若锁被撤销后仍由原线程持有，可重新偏向以减少升级成本。  
- **触发条件**：  
  - 撤销次数 < 阈值（默认20次）  
  - 原线程再次获取锁时，JVM通过`Mark Word`中的`biased_lock`位标记重偏向。  
  ```java
  // 示例：重偏向场景
  synchronized(obj) { // 线程A首次获取，设置偏向
    // 线程B竞争导致撤销
  }
  synchronized(obj) { // 线程A再次获取，触发重偏向
  }
  ```

---

### synchronized vs ReentrantLock 对比  
| **维度**       | **synchronized**                          | **ReentrantLock**                          |
|----------------|------------------------------------------|-------------------------------------------|
| **底层实现**   | JVM层（基于Monitor）                     | API层（基于AQS + CAS）                    |
| **性能**       | 低竞争时优化后性能接近ReentrantLock      | 高竞争时更灵活（支持自旋、超时）          |
| **功能扩展**   | 不可中断、无超时、非公平锁               | 可中断、超时、公平锁、多Condition         |
| **典型场景**   | 简单同步块（如单例）                     | 复杂业务（如限流、超时控制）              |

**核心差异解析**：  
1. **底层机制**：  
   - `synchronized`依赖JVM的Monitor对象，锁状态存储在对象头`Mark Word`中。  
   - `ReentrantLock`通过AQS的`state`变量管理锁状态，结合CAS实现非阻塞算法。  
   ```java
   // ReentrantLock底层AQS结构
   AQS -> state (锁状态) |-> 同步队列（等待线程）
   ```

2. **性能对比**：  
   - **低竞争**：`synchronized`经JVM优化（如偏向锁、自旋锁）后性能优异。  
   - **高竞争**：`ReentrantLock`可通过`tryLock(timeout)`避免线程长时间阻塞，减少上下文切换。  

3. **功能差异**：  
   ```java
   // ReentrantLock支持超时与中断
   lock.tryLock(1, TimeUnit.SECONDS); 
   lock.lockInterruptibly(); 
   ```

**选型建议**：  
- 优先`synchronized`（JVM持续优化，代码简洁）；  
- 需高级特性（如公平锁、多条件变量）时选`ReentrantLock`。'),
  ('java-020', '

### AQS 核心源码解析（参考回答）

#### 1. **双向同步队列**
- **为什么**：  
  AQS通过双向链表实现的同步队列管理线程竞争状态，核心目的是高效支持线程的排队与唤醒。双向结构允许快速定位头尾节点（O(1)时间），同时支持线程在等待时直接访问前驱节点的状态（如判断是否可获取锁）。
  
- **怎么做**：  
  - 队列节点（`Node`）包含`prev`/`next`指针、线程引用、等待状态（`waitStatus`）等字段。  
  - 线程获取锁失败时，通过`addWaiter()`入队，CAS操作确保线程安全。  
  - 示例：  
    ```java
    // Node结构
    static final class Node {
        volatile Node prev;
        volatile Node next;
        Thread thread;
        volatile int waitStatus; // SIGNAL, CANCELLED等
    }
    ```

#### 2. **独占/共享模式**
- **为什么**：  
  独占模式（如`ReentrantLock`）保证互斥访问，共享模式（如`CountDownLatch`）允许多线程并发获取资源。两者通过统一框架复用队列管理逻辑，减少代码冗余。

- **怎么做**：  
  - **独占模式**：`acquire()`调用`tryAcquire()`尝试获取锁，失败则入队并自旋重试。  
  - **共享模式**：`acquireShared()`通过`tryAcquireShared()`返回剩余资源量，允许多线程同时通过。  
  - 关键流程：  
    ```java
    public final void acquire(int arg) {
        if (!tryAcquire(arg) && acquireQueued(addWaiter(Node.EXCLUSIVE), arg))
            selfInterrupt();
    }
    ```

#### 3. **Condition等待队列**
- **为什么**：  
  `Condition`将线程等待与锁解耦，支持多条件分支（如生产者-消费者模型）。等待队列独立于同步队列，避免干扰主锁竞争。

- **怎么做**：  
  - 线程调用`await()`时，从同步队列移出并加入`Condition`队列。  
  - 被`signal()`唤醒后，重新加入同步队列尾部。  
  - 示例：  
    ```java
    // Condition队列结构
    ConditionObject {
        Node firstWaiter; // 等待队列头
        Node lastWaiter;  // 等待队列尾
    }
    ```

#### 架构图示
```
同步队列（主队列）          Condition等待队列
[Head] <-> [Node1] <-> [Node2]   [Node1] -> [Node2]
     ↑ 线程竞争锁              ↑ 线程等待条件
```

#### 总结
AQS通过**状态变量+队列**的抽象，统一了锁、信号量等并发工具的实现。双向队列保障高效排队，独占/共享模式覆盖不同场景，`Condition`实现条件等待的灵活性。源码中大量使用CAS和自旋优化性能，是JUC并发框架的基石。'),
  ('java-021', '

### ReentrantLock 公平/非公平锁与可重入实现解析  

#### 1. **公平锁 vs 非公平锁**  
**为什么需要区分？**  
- **公平锁**：保证线程按 FIFO 顺序获取锁，避免饥饿（如线程 A 一直阻塞线程 B）。  
- **非公平锁**：允许“插队”，性能更高（减少线程切换开销），但可能引发饥饿。  

**底层实现差异**  
- **公平锁**：  
  - 获取锁时，先检查 AQS 等待队列是否有前驱节点（`hasQueuedPredecessors()`）。  
  - 若存在等待线程，则当前线程必须排队。  
  ```java
  // FairSync.tryAcquire()
  if (hasQueuedPredecessors() || !compareAndSetState(0, acquires))
      return false;
  ```  
- **非公平锁**：  
  - 直接尝试 CAS 修改 `state`，失败后再检查队列。  
  ```java
  // NonfairSync.tryAcquire()
  if (compareAndSetState(0, acquires)) {
      setExclusiveOwnerThread(current);
      return true;
  }
  ```  

**场景选择**  
- 高并发场景优先非公平锁（如 Dubbo RPC 调用），低延迟场景用公平锁（如数据库连接池）。  

---

#### 2. **可重入机制**  
**为什么需要可重入？**  
- 避免同一线程重复加锁时死锁（如方法 A 调用方法 B，两者均加锁）。  

**底层实现**  
- 通过 AQS 的 `state` 计数器 + 持有锁线程标识：  
  - 每次成功获取锁时 `state++`，释放时 `state--`。  
  - 仅当 `state=0` 时才真正释放锁。  
  ```java
  // ReentrantLock.lock() 可重入逻辑
  if (currentThread == getExclusiveOwnerThread()) {
      setState(state + acquires); // 累加计数器
      return;
  }
  ```  

**关键设计**  
- `exclusiveOwnerThread` 记录持有锁的线程，确保只有该线程可重入。  
- 释放锁时，需循环 `unlock()` 直到 `state=0`（对应多次 `lock()`）。  

---

#### 3. **核心流程图解**  
```
Client -> ReentrantLock -> AQS (state, wait queue)
|-> FairSync: check queue before CAS
|-> NonfairSync: CAS first, queue if fail
|-> state: 0 (free) / 1 (locked) / 2+ (reentrant)
```  

**总结**  
- 公平性通过队列检查实现，非公平性通过“先试后排队”优化性能。  
- 可重入依赖 `state` 计数器和线程标识，是 AQS 的通用设计模式。  

（字数：598）'),
